INSERT INTO games (id, title, title_en, pinyin, author, maker, source, score, players, plays, year, cat, tags, hue, chroma, play, src, demo, fable, hot, neu, featured, pick, wide, duration, origin, banner, banner_en, blurb, blurb_en, about, about_en, poster, pw, ph, pos, shots, shotSize, dist, ord, at, packStatus, ownerId, embed) VALUES ('evensong', 'Evensong', '', '', 'Kevin Ngo', '', 'X', NULL, '244', 0, 2026, 'action', '["动作","魂like"]', 250, 0.1, 'io', 'https://evensong-phi.vercel.app/', 0, 1, 1, 1, 1, 1, 1, 'mid', 'x', '画面就在原页里', 'assets/posters/evensong.jpg', '沉没的主教堂里，只打这一场。画面就在原页。', 'One fight in a sunken cathedral. The original page is the picture.', 'Kevin Ngo 用 Fable 5.2 做的魂like Boss 战，原页托管在 evensong-phi.vercel.app。封面是作者公开的分享卡。在即玩里直接打开原作。', 'Kevin Ngo’s Fable 5.2 soulslike boss fight, hosted at evensong-phi.vercel.app. Cover is the author’s public share card. Opens the original right here.', 'The picture is on the original page', 1200, 630, 'center', '["assets/posters/evensong.jpg"]', '[[1200,630]]', '[0,0,0,0,0]', 0, 1794592579729, '', '', 1);
INSERT INTO games (id, title, title_en, pinyin, author, maker, source, score, players, plays, year, cat, tags, hue, chroma, play, src, demo, fable, hot, neu, featured, pick, wide, duration, origin, banner, banner_en, blurb, blurb_en, about, about_en, poster, pw, ph, pos, shots, shotSize, dist, ord, at, packStatus, ownerId, embed) VALUES ('breach', '穿越火线', 'CrossFire', 'chuanyuehuoxian cf', 'hanyue.io', '', '', NULL, '19', 0, 2026, 'action', '["射击","联机","CF"]', 20, 0.1, 'io', 'https://cf.hanyue.io/', 0, 0, 1, 1, 1, 1, 1, 'mid', 'hosted', '起个名字就能进', 'assets/posters/breach.jpg', '玩CF。起个名字进大厅，运输船等多图可打。', 'Play CF. Pick a name, walk into the lobby, fight on Transport Ship and other maps.', 'hanyue.io 托管的穿越火线网页联机局，原页是 BREACH 大厅。原作要在 hanyue.io 自己的页面里保存昵称 Cookie，嵌在即玩里进不了大厅，点「去原页玩 ↗」在新窗口打开。', 'A CrossFire web lobby hosted at cf.hanyue.io (BREACH). It needs to save a nickname cookie on its own page, so it cannot get past the lobby when embedded here. Use “Play on original ↗” to open it in a new tab.', 'Pick a name and walk in', 960, 540, 'center', '["assets/posters/breach.jpg"]', '[[960,540]]', '[0,0,0,0,0]', 1, 1794592579729, '', '', 0);
INSERT INTO games (id, title, title_en, pinyin, author, maker, source, score, players, plays, year, cat, tags, hue, chroma, play, src, demo, fable, hot, neu, featured, pick, wide, duration, origin, banner, banner_en, blurb, blurb_en, about, about_en, poster, pw, ph, pos, shots, shotSize, dist, ord, at, packStatus, ownerId, embed) VALUES ('warm-toy-room', '双人成行 · 暖光玩具房', 'It Takes Two · Warm Toy Room', 'shuangrenchengxing nanguang wanju', '大肥鱼', '', '', NULL, '26', 0, 2026, 'action', '["平台","联机"]', 35, 0.1, 'io', 'https://v25.dafeiyugame.site/', 0, 0, 1, 1, 1, 1, 1, 'mid', 'hosted', '换人，把星星搬回家', 'assets/posters/warm-toy-room.jpg', '大肥鱼的双人成行网页试玩。在暖光玩具房里跑跳、换人，收集五枚星光。', 'Da Fei Yu’s It Takes Two web demo. Run, swap, and gather five starlights in a warm toy room.', '原页托管在 v25.dafeiyugame.site，V30 网页试玩。封面是启动页实机。在即玩里直接打开原作。', 'Hosted at v25.dafeiyugame.site, V30 web demo. Cover is the live splash. Opens the original right here.', 'Swap, bring the stars home', 960, 540, 'center', '["assets/posters/warm-toy-room.jpg"]', '[[960,540]]', '[0,0,0,0,0]', 2, 1794592579729, 'listed', 'dafeiyu', 1);
INSERT INTO games (id, title, title_en, pinyin, author, maker, source, score, players, plays, year, cat, tags, hue, chroma, play, src, demo, fable, hot, neu, featured, pick, wide, duration, origin, banner, banner_en, blurb, blurb_en, about, about_en, poster, pw, ph, pos, shots, shotSize, dist, ord, at, packStatus, ownerId, embed) VALUES ('feiche-3d', 'QQ飞车', 'QQ Speed', 'qqfeiche feiche', '', '', '腾讯（IP）', NULL, '67', 0, 2026, 'action', '["竞速","工坊"]', 20, 0.1, 'io', 'https://lf3-static.bytednsdoc.com/obj/eden-cn/nulojnulwlo/qqfeiche3d/index.html', 0, 1, 1, 1, 1, 1, 1, 'mid', 'fable52', '氮气一开就能漂', 'assets/posters/feiche-3d.jpg', '漂移攒能量，氮气和道具，四条复古赛道。原页可玩。', 'Drift for energy, nitro and items, four retro tracks. The original page is playable.', 'QQ飞车 3D 网页局，字节静态托管。在即玩里直接打开原作，原页托管在 lf3-static.bytednsdoc.com。', 'QQ Speed 3D in the browser, hosted on ByteDance CDN. Opens the original from lf3-static.bytednsdoc.com right here.', 'Nitro on, drift away', 960, 540, 'center', '["assets/posters/feiche-3d.jpg"]', '[[960,540]]', '[0,0,0,0,0]', 3, 1794592579729, '', '', 1);
INSERT INTO games (id, title, title_en, pinyin, author, maker, source, score, players, plays, year, cat, tags, hue, chroma, play, src, demo, fable, hot, neu, featured, pick, wide, duration, origin, banner, banner_en, blurb, blurb_en, about, about_en, poster, pw, ph, pos, shots, shotSize, dist, ord, at, packStatus, ownerId, embed) VALUES ('hextech-aram', '英雄联盟 · 海克斯大乱斗', 'League of Legends · Hextech ARAM', 'yingxionglianmeng yxlm lol aram haikesidaluandou', 'hanyue.io', '', '', NULL, '41', 0, 2026, 'action', '["MOBA","联机"]', 220, 0.1, 'io', 'https://lol.hanyue.io/', 0, 0, 1, 1, 1, 1, 1, 'mid', 'hosted', '选个英雄上冰桥', 'assets/posters/hextech-aram.jpg', '选一个英雄，在冰桥上乱斗。原页可玩。', 'Pick a champion and brawl on the ice bridge. The original page is playable.', '英雄联盟海克斯大乱斗网页局，原页托管在 lol.hanyue.io。原作要在 hanyue.io 自己的页面里保存昵称 Cookie，嵌在即玩里进不了游戏，点「去原页玩 ↗」在新窗口打开。', 'A Hextech ARAM web brawl hosted at lol.hanyue.io. It needs to save a nickname cookie on its own page, so it cannot start when embedded here. Use “Play on original ↗” to open it in a new tab.', 'Pick a champion, hit the ice', 960, 540, 'center', '["assets/posters/hextech-aram.jpg"]', '[[960,540]]', '[0,0,0,0,0]', 4, 1794592579729, '', '', 0);
INSERT INTO games (id, title, title_en, pinyin, author, maker, source, score, players, plays, year, cat, tags, hue, chroma, play, src, demo, fable, hot, neu, featured, pick, wide, duration, origin, banner, banner_en, blurb, blurb_en, about, about_en, poster, pw, ph, pos, shots, shotSize, dist, ord, at, packStatus, ownerId, embed) VALUES ('last-light', 'Last Light', '', '', 'Deny224', '', 'X', NULL, '本周上架', 0, 2026, 'action', '["生存","动作"]', 70, 0.12, 'story', 'https://deny224.itch.io/last-light', 0, 0, 1, 1, 1, 1, 1, 'mid', 'x', '灯笼就是血条', 'assets/posters/last-light-1.jpg', '灯笼就是血条。浏览器里直接开的 3D 夜林。', 'The lantern is the health bar. A 3D night wood that opens in the browser.', '作者 Deny224 在 X 发出的免费浏览器生存。原作托管在 deny224.itch.io，无法嵌进即玩，点「去原页玩 ↗」在新窗口打开。', 'Deny224 posted this free browser survival on X. The original lives at deny224.itch.io and cannot be embedded here. Use “Play on original ↗” to open it in a new tab.', 'The lantern is the health bar', 1568, 722, 'center 42%', '["assets/posters/last-light-1.jpg","assets/posters/last-light-3.jpg","assets/posters/last-light-2.jpg"]', '[[1568,722],[1568,722],[1568,722]]', '[0,0,0,0,0]', 5, 1794592579729, '', '', 0);
INSERT INTO games (id, title, title_en, pinyin, author, maker, source, score, players, plays, year, cat, tags, hue, chroma, play, src, demo, fable, hot, neu, featured, pick, wide, duration, origin, banner, banner_en, blurb, blurb_en, about, about_en, poster, pw, ph, pos, shots, shotSize, dist, ord, at, packStatus, ownerId, embed) VALUES ('akoben', 'AKOBEN', '', '', 'Eddie Forson', '', 'X', NULL, '本周上架', 0, 2026, 'action', '["动作","Boss"]', 25, 0.12, 'io', 'https://play.akoben-game.com/', 0, 0, 0, 1, 1, 1, 0, 'mid', 'x', '', 'assets/posters/akoben.jpg', '六足攻城机走进节日集市。打断两只膝盖，它就会跪下。', 'A six-legged siege walker enters a festival market. Break both knees and it kneels.', 'Kiseki Labs 的浏览器序章 Boss「The Sovereign」。封面是作者发在 X 上的角色海报。在即玩里直接打开原作，原页托管在 play.akoben-game.com。', 'Kiseki Labs’ browser prologue boss, The Sovereign. Cover is the character poster the author posted on X. Opens the original from play.akoben-game.com right here.', '', 1080, 1350, 'center 35%', '["assets/posters/akoben.jpg"]', '[[1080,1350]]', '[0,0,0,0,0]', 6, 1794592579729, '', '', 1);
INSERT INTO games (id, title, title_en, pinyin, author, maker, source, score, players, plays, year, cat, tags, hue, chroma, play, src, demo, fable, hot, neu, featured, pick, wide, duration, origin, banner, banner_en, blurb, blurb_en, about, about_en, poster, pw, ph, pos, shots, shotSize, dist, ord, at, packStatus, ownerId, embed) VALUES ('we-fishing', 'We Fishing', '', '', 'Mangolotis', '', 'X', NULL, '本周上架', 0, 2026, 'idle', '["放置","钓鱼"]', 40, 0.1, 'clicker', 'https://www.mangolotis.com/wefishing/', 0, 0, 0, 1, 1, 1, 1, 'mid', 'x', '钓鱼、听歌、留言', 'assets/posters/we-fishing.jpg', '钓鱼、听歌、留一句。作者说玩法几乎什么也没有。', 'Fish, listen to a song, leave a line. The author says there is almost no gameplay.', 'Mangolotis 在 X 发出的网页钓鱼。封面是秋日池塘的实机。在即玩里直接打开原作，原页托管在 mangolotis.com。', 'Mangolotis posted this web fishing game on X. Cover is a live shot of the autumn pond. Opens the original from mangolotis.com right here.', 'Fish, listen, leave a note', 1787, 806, 'center 58%', '["assets/posters/we-fishing.jpg"]', '[[1787,806]]', '[0,0,0,0,0]', 7, 1794592579729, '', '', 1);
INSERT INTO games (id, title, title_en, pinyin, author, maker, source, score, players, plays, year, cat, tags, hue, chroma, play, src, demo, fable, hot, neu, featured, pick, wide, duration, origin, banner, banner_en, blurb, blurb_en, about, about_en, poster, pw, ph, pos, shots, shotSize, dist, ord, at, packStatus, ownerId, embed) VALUES ('mustache-protocol', 'Mustache Protocol', '', '', 'Henry Cavill', '', 'X', NULL, '本周上架', 0, 2026, 'action', '["动作","像素"]', 70, 0.12, 'io', 'https://mustacheprotocol.withgoogle.com/', 0, 0, 1, 1, 1, 1, 0, 'mid', 'x', '', 'assets/posters/mustache-1.jpg', '胡子骑士拿着电锯剑。浏览器里能开。', 'A mustache knight with a chainsaw sword. It opens in the browser.', 'ScreenTime 在 X 转的 Henry Cavill AI 网页游戏。封面是作者放出的像素立绘。原作托管在 mustacheprotocol.withgoogle.com，无法嵌进即玩，点「去原页玩 ↗」在新窗口打开。', 'A Henry Cavill AI web game ScreenTime posted on X. Cover is the author’s pixel standee. The original lives at mustacheprotocol.withgoogle.com and cannot be embedded here. Use “Play on original ↗” to open it in a new tab.', '', 1400, 1400, 'center 22%', '["assets/posters/mustache-1.jpg","assets/posters/mustache-2.jpg"]', '[[1400,1400],[1400,1400]]', '[0,0,0,0,0]', 8, 1794592579729, '', '', 0);
INSERT INTO games (id, title, title_en, pinyin, author, maker, source, score, players, plays, year, cat, tags, hue, chroma, play, src, demo, fable, hot, neu, featured, pick, wide, duration, origin, banner, banner_en, blurb, blurb_en, about, about_en, poster, pw, ph, pos, shots, shotSize, dist, ord, at, packStatus, ownerId, embed) VALUES ('laps', 'Laps', '', '', 'Dan Clarke', '', 'X', NULL, '本周上架', 0, 2026, 'action', '["竞速","桌面"]', 50, 0.1, 'io', '', 0, 0, 0, 1, 1, 1, 1, 'short', 'x', '课桌上的迷你圈速', 'assets/posters/laps-2.jpg', '数学课本旁边在赛车。Xbox 自带浏览器也能开。', 'A race next to a math book. The Xbox’s own browser can open it.', 'Dan Clarke 周末做的网页圈速，封面是餐桌上的实机。暂时没找到作者公开的可玩地址，这里只做介绍。', 'A web time-trial Dan Clarke made over a weekend. Cover is a live shot on a dining table. No public playable page found yet. This page is an introduction only.', 'Mini laps on a desk', 1920, 1080, 'center 48%', '["assets/posters/laps-2.jpg","assets/posters/laps-1.jpg"]', '[[1920,1080],[1920,1080]]', '[0,0,0,0,0]', 9, 1794592579729, '', '', 1);
