INSERT INTO games (id, title, title_en, pinyin, author, maker, source, score, players, plays, year, cat, tags, hue, chroma, play, src, demo, fable, hot, neu, featured, pick, wide, duration, origin, banner, banner_en, blurb, blurb_en, about, about_en, poster, pw, ph, pos, shots, shotSize, dist, ord, at, packStatus, ownerId, embed) VALUES ('fluff-bat', 'Fluff Bat Flight', '', '', 'BlackLight.ink', '', 'X', NULL, '本周上架', 0, 2026, 'action', '["动作","休闲"]', 300, 0.1, 'io', '', 0, 0, 0, 1, 1, 0, 0, 'short', 'x', '', 'assets/posters/fluff-bat.jpg', '选一只绒蝠，穿过宫殿，捡蛋，躲大蒜。', 'Pick a fluff bat, fly the palace, grab eggs, dodge garlic.', '为 Fluff Bat 比赛做的网页飞行。封面是作者发在 X 上的海报。暂时没找到作者公开的可玩地址，这里只做介绍。', 'A web flyer for the Fluff Bat contest. Cover is the poster the author posted on X. No public playable page found yet. This page is an introduction only.', '', 1600, 900, 'center 40%', '["assets/posters/fluff-bat.jpg"]', '[[1600,900]]', '[0,0,0,0,0]', 12, 1794592579729, '', '', 1);
INSERT INTO games (id, title, title_en, pinyin, author, maker, source, score, players, plays, year, cat, tags, hue, chroma, play, src, demo, fable, hot, neu, featured, pick, wide, duration, origin, banner, banner_en, blurb, blurb_en, about, about_en, poster, pw, ph, pos, shots, shotSize, dist, ord, at, packStatus, ownerId, embed) VALUES ('sams-pizza', 'A Day at Sam''s Pizza', '', '', 'CollectorDev', '', 'X', NULL, '本周上架', 0, 2026, 'puzzle', '["模拟","像素"]', 50, 0.1, 'story', 'https://collectordev09.itch.io/a-day-at-sams-pizza', 0, 0, 0, 1, 0, 0, 0, 'short', 'x', '', 'assets/posters/sams-pizza-2.png', '夜里的披萨店。客人要一块，你来配单。', 'A pizza shop at night. A guest wants a slice. You build the order.', 'CollectorDev 在 X 发出的网页店。封面是点单实机。原作托管在 collectordev09.itch.io，无法嵌进即玩，点「去原页玩 ↗」在新窗口打开。', 'CollectorDev posted this web shop on X. Cover is a live order screen. The original lives at collectordev09.itch.io and cannot be embedded here. Use “Play on original ↗” to open it in a new tab.', '', 800, 600, 'center 40%', '["assets/posters/sams-pizza-2.png","assets/posters/sams-pizza-1.png"]', '[[800,600],[800,600]]', '[0,0,0,0,0]', 13, 1794592579729, '', '', 0);
INSERT INTO games (id, title, title_en, pinyin, author, maker, source, score, players, plays, year, cat, tags, hue, chroma, play, src, demo, fable, hot, neu, featured, pick, wide, duration, origin, banner, banner_en, blurb, blurb_en, about, about_en, poster, pw, ph, pos, shots, shotSize, dist, ord, at, packStatus, ownerId, embed) VALUES ('water-keeps', 'What the Water Keeps', '', '', 'Kevin Ngo', '', '', NULL, '314', 0, 2026, 'story', '["探索","叙事"]', 200, 0.1, 'story', 'https://what-the-water-keeps.vercel.app/', 0, 1, 1, 1, 1, 1, 1, 'mid', 'fable52', '八界泛舟', 'assets/posters/water-keeps.jpg', '坐船穿过八个不像同一世界的水域。灯笼亮着，你可以自己划。', 'Row through eight waters that do not feel like one world. Lanterns stay on. You paddle.', 'Kevin Ngo 用 Fable 5.2 做的浏览器泛舟。X 上这周还在转。封面来自 fable52.games。在即玩里直接打开原作，原页托管在 what-the-water-keeps.vercel.app。', 'Kevin Ngo’s browser boat, made in Fable 5.2. Still circulating on X this week. Cover from fable52.games. Opens the original from what-the-water-keeps.vercel.app right here.', 'Eight waters, one boat', 960, 540, 'center', '["assets/posters/water-keeps.jpg"]', '[[960,540]]', '[0,0,0,0,0]', 14, 1794592579729, '', '', 1);
INSERT INTO games (id, title, title_en, pinyin, author, maker, source, score, players, plays, year, cat, tags, hue, chroma, play, src, demo, fable, hot, neu, featured, pick, wide, duration, origin, banner, banner_en, blurb, blurb_en, about, about_en, poster, pw, ph, pos, shots, shotSize, dist, ord, at, packStatus, ownerId, embed) VALUES ('mothlight', 'MOTHLIGHT // Vesper-9', '', '', '', 'Fable 5.2', 'fable52.games', NULL, '320', 0, 2026, 'action', '["竞速","赛博"]', 300, 0.1, 'io', 'https://fable52.games/api/sandbox/mothlight', 0, 1, 1, 1, 1, 1, 0, 'mid', 'fable52', '', 'assets/posters/mothlight.jpg', '雨夜里穿过五座城区，把十二道光门串起来。', 'Cut through five districts in the rain and string twelve light gates together.', 'fable52.games 收录的单文件赛博竞速。封面是原站缩略图。在即玩里直接打开原作。', 'A single-file cyber racer listed on fable52.games. Cover is the original thumbnail. Opens the original right here.', '', 960, 540, 'center', '["assets/posters/mothlight.jpg"]', '[[960,540]]', '[0,0,0,0,0]', 15, 1794592579729, '', '', 1);
INSERT INTO games (id, title, title_en, pinyin, author, maker, source, score, players, plays, year, cat, tags, hue, chroma, play, src, demo, fable, hot, neu, featured, pick, wide, duration, origin, banner, banner_en, blurb, blurb_en, about, about_en, poster, pw, ph, pos, shots, shotSize, dist, ord, at, packStatus, ownerId, embed) VALUES ('bayhaven', 'Bayhaven', '', '', '', 'Fable 5.2', 'fable52.games', NULL, '330', 0, 2026, 'action', '["开放世界","驾驶"]', 40, 0.1, 'io', 'https://fablestar.games/play/', 0, 1, 1, 1, 1, 1, 0, 'mid', 'fable52', '', 'assets/posters/bayhaven.jpg', '一场现场写出来的开放世界。开车，逛城，把旧账了结。', 'An open world written on the spot. Drive, walk the city, settle an old bill.', 'Fable 5.2 一次长会话写完的犯罪开放世界。封面来自 fable52.games。在即玩里直接打开原作，原页托管在 fablestar.games。', 'A crime open world written in one long Fable 5.2 session. Cover from fable52.games. Opens the original from fablestar.games right here.', '', 960, 540, 'center', '["assets/posters/bayhaven.jpg"]', '[[960,540]]', '[0,0,0,0,0]', 16, 1794592579729, '', '', 1);
