INSERT INTO games (id, title, title_en, pinyin, author, maker, source, score, players, plays, year, cat, tags, hue, chroma, play, src, demo, fable, hot, neu, featured, pick, wide, duration, origin, banner, banner_en, blurb, blurb_en, about, about_en, poster, pw, ph, pos, shots, shotSize, dist, ord, at, packStatus, ownerId, embed) VALUES ('blameless', 'BLAMELESS', '', '', '', 'Fable 5.2', 'fable52.games', NULL, '340', 0, 2026, 'action', '["射击","工坊"]', 145, 0.1, 'io', 'https://blameless.petruha.ge/', 0, 1, 1, 1, 0, 1, 0, 'mid', 'fable52', '', 'assets/posters/blameless.jpg', '凌晨 3:07，生产挂了。你亲自 kubectl exec 进去。', '03:07. Production is down. You kubectl exec in yourself.', '值班程序员题材的 FPS。封面来自 fable52.games。原作托管在 blameless.petruha.ge，无法嵌进即玩，点「去原页玩 ↗」在新窗口打开。', 'An FPS about being on call. Cover from fable52.games. The original lives at blameless.petruha.ge and cannot be embedded here. Use “Play on original ↗” to open it in a new tab.', '', 960, 540, 'center', '["assets/posters/blameless.jpg"]', '[[960,540]]', '[0,0,0,0,0]', 19, 1794592579729, '', '', 0);
