INSERT INTO games (id, title, title_en, pinyin, author, maker, source, score, players, plays, year, cat, tags, hue, chroma, play, src, demo, fable, hot, neu, featured, pick, wide, duration, origin, banner, banner_en, blurb, blurb_en, about, about_en, poster, pw, ph, pos, shots, shotSize, dist, ord, at, packStatus, ownerId, embed) VALUES ('fable-multiplayer', 'Fable 5.2 联机局', 'Fable 5.2 Multiplayer', '', 'Ahmad K. Mozaffar', '', 'X', NULL, '本周上架', 0, 2026, 'action', '["工坊","联机"]', 145, 0.1, 'io', '', 0, 1, 0, 1, 0, 0, 0, 'mid', 'x', '', 'assets/posters/fable-multiplayer.jpg', '几分钟做出能联机的一局，连资源都是现场生成的。', 'A multiplayer round in a few minutes. Even the assets are generated on the spot.', 'Ahmad 昨天在 X 发出的 Fable 5.2 联机演示。封面是作者原帖实机。暂时没找到作者公开的可玩地址，这里只做介绍。', 'Ahmad posted this Fable 5.2 multiplayer demo on X yesterday. Cover is the author’s live capture. No public playable page found yet. This page is an introduction only.', '', 1199, 445, 'center 30%', '["assets/posters/fable-multiplayer.jpg"]', '[[1199,445]]', '[0,0,0,0,0]', 44, 1794592579729, '', '', 1);
