INSERT INTO games (id, title, title_en, pinyin, author, maker, source, score, players, plays, year, cat, tags, hue, chroma, play, src, demo, fable, hot, neu, featured, pick, wide, duration, origin, banner, banner_en, blurb, blurb_en, about, about_en, poster, pw, ph, pos, shots, shotSize, dist, ord, at, packStatus, ownerId, embed) VALUES ('cookie-clicker', 'Cookie Clicker', '', '', 'Orteil', '', '', 9.4, '128.6万', 0, 2013, 'idle', '["放置","点击"]', 70, 0.12, 'clicker', 'https://orteil.dashnet.org/cookieclicker/', 0, 0, 1, 0, 0, 1, 1, 'long', '', '没有关卡，也没有结局', 'assets/posters/cookie-clicker.jpg', '没有关卡，也没有结局。饼干会一直等你。', 'No levels. No ending. The cookies will wait.', '从一块饼干开始，点出烤箱、工厂和宇宙。原作托管在 orteil.dashnet.org，无法嵌进即玩，点「去原页玩 ↗」在新窗口打开。', 'Start with one cookie. Click out ovens, factories, a universe. The original lives at orteil.dashnet.org and cannot be embedded here. Use “Play on original ↗” to open it in a new tab.', 'No levels. No ending.', 1920, 1080, 'center 40%', '["assets/posters/cookie-clicker.jpg","assets/posters/cookie-2.jpg"]', '[[1920,1080],[1920,1080]]', '[2,3,8,27,60]', 59, 1794592579729, '', '', 0);
INSERT INTO games (id, title, title_en, pinyin, author, maker, source, score, players, plays, year, cat, tags, hue, chroma, play, src, demo, fable, hot, neu, featured, pick, wide, duration, origin, banner, banner_en, blurb, blurb_en, about, about_en, poster, pw, ph, pos, shots, shotSize, dist, ord, at, packStatus, ownerId, embed) VALUES ('2048', '2048', '', '', 'Gabriele Cirulli', '', '', 9.1, '96.2万', 0, 2014, 'puzzle', '["解谜","滑动"]', 50, 0.14, 'merge', '/vendor/2048/', 0, 0, 1, 0, 0, 1, 0, 'short', '', '', 'assets/posters/2048.jpg', '规则三秒就懂，512 开始手会抖。', 'The rule takes three seconds. Your hands start to shake at 512.', '在 4×4 格子里把数字合成 2048。这是 Gabriele Cirulli 开源（MIT）的原版，由即玩自托管，直接在这里玩；官方版在 play2048.co。', 'Slide tiles on a 4×4 grid until you make 2048. This is Gabriele Cirulli''s open-source (MIT) original, self-hosted by Jiwan so it plays right here; the official site is play2048.co.', '', 1200, 630, 'center', '["assets/posters/2048.jpg","assets/posters/2048.png"]', '[[1200,630],[548,549]]', '[3,5,12,31,49]', 60, 1794592579729, '', '', 1);
INSERT INTO games (id, title, title_en, pinyin, author, maker, source, score, players, plays, year, cat, tags, hue, chroma, play, src, demo, fable, hot, neu, featured, pick, wide, duration, origin, banner, banner_en, blurb, blurb_en, about, about_en, poster, pw, ph, pos, shots, shotSize, dist, ord, at, packStatus, ownerId, embed) VALUES ('a-dark-room', 'A Dark Room', '', '', 'Doublespeak Games', '', '', 9.6, '41.8万', 0, 2013, 'story', '["叙事","文字"]', 40, 0.04, 'story', 'https://adarkroom.doublespeakgames.com/', 0, 0, 0, 0, 0, 1, 0, 'long', '', '', 'assets/posters/a-dark-room.jpg', '先把火点燃。其余的事，火光里会慢慢出现。', 'Light the fire first. The rest shows up in the glow.', '火堆、木头、门外的声音。在即玩里直接打开原作，原页托管在 adarkroom.doublespeakgames.com。', 'Fire, wood, a sound outside the door. Opens the original from adarkroom.doublespeakgames.com right here.', '', 1920, 1080, 'center', '["assets/posters/a-dark-room.jpg"]', '[[1920,1080]]', '[1,2,6,22,69]', 61, 1794592579729, '', '', 1);
