INSERT INTO games (id, title, title_en, pinyin, author, maker, source, score, players, plays, year, cat, tags, hue, chroma, play, src, demo, fable, hot, neu, featured, pick, wide, duration, origin, banner, banner_en, blurb, blurb_en, about, about_en, poster, pw, ph, pos, shots, shotSize, dist, ord, at, packStatus, ownerId, embed) VALUES ('watermelon', '合成大西瓜', 'Merge Watermelon', 'hechengdaxigua xigua daxigua', '公开网页游戏', '', '', 8.2, '310.5万', 0, 2021, 'puzzle', '["休闲","合成"]', 15, 0.14, 'merge', 'https://www.wesane.com/game/654/', 0, 0, 1, 1, 0, 0, 0, 'short', '', '', 'assets/posters/watermelon.png', '小圆碰小圆。大家都在等那颗西瓜。', 'Small circles bump small circles. Everyone is waiting for that watermelon.', '原作是下落合成。在即玩里直接打开原作，原页托管在 wesane.com。', 'The original is a drop-and-merge. Opens the original from wesane.com right here.', '', 421, 237, 'center', '["assets/posters/watermelon.png"]', '[[421,237]]', '[7,12,24,31,26]', 68, 1794592579729, '', '', 1);
INSERT INTO games (id, title, title_en, pinyin, author, maker, source, score, players, plays, year, cat, tags, hue, chroma, play, src, demo, fable, hot, neu, featured, pick, wide, duration, origin, banner, banner_en, blurb, blurb_en, about, about_en, poster, pw, ph, pos, shots, shotSize, dist, ord, at, packStatus, ownerId, embed) VALUES ('slither', 'Slither.io', '', '', 'Steve Howse', '', '', 8.5, '176.3万', 0, 2016, 'action', '["动作","IO"]', 155, 0.13, 'io', 'https://slither.io/', 0, 0, 1, 0, 0, 0, 0, 'mid', '', '', 'assets/posters/slither.png', '变长，围人，别把自己绕进去。', 'Grow long, wrap people, do not loop yourself.', '蛇形 IO。原作托管在 slither.io，无法嵌进即玩，点「去原页玩 ↗」在新窗口打开。', 'A snake IO. The original lives at slither.io and cannot be embedded here. Use “Play on original ↗” to open it in a new tab.', '', 1358, 624, 'center 42%', '["assets/posters/slither.png"]', '[[1358,624]]', '[5,9,21,35,30]', 69, 1794592579729, '', '', 0);
INSERT INTO games (id, title, title_en, pinyin, author, maker, source, score, players, plays, year, cat, tags, hue, chroma, play, src, demo, fable, hot, neu, featured, pick, wide, duration, origin, banner, banner_en, blurb, blurb_en, about, about_en, poster, pw, ph, pos, shots, shotSize, dist, ord, at, packStatus, ownerId, embed) VALUES ('harbor', '港口调度', 'Harbor Dispatch', 'gangkoudiaodu gangkou', '何予', '', '', 8.4, '12.8万', 0, 2026, 'idle', '["工坊","调度"]', 230, 0.09, 'story', '', 1, 1, 0, 1, 0, 0, 0, 'mid', '', '', '', '潮汐窗口只有八分钟。把船位、吊机和夜班排开。', 'The tide window is eight minutes. Slot the berths, cranes, and night shift.', 'Fable 5.2 工坊示例，非正式上架。这是即玩站内做的简短示例，不是完整作品。', 'A Fable 5.2 workshop sample, not a live listing. This is a short sample built on Jiwan, not a full game.', '', 960, 540, 'center', '["早班船位","吊机冲突","夜潮"]', '[]', '[4,8,18,30,40]', 70, 1794592579729, 'listed', 'heyu', 1);
INSERT INTO games (id, title, title_en, pinyin, author, maker, source, score, players, plays, year, cat, tags, hue, chroma, play, src, demo, fable, hot, neu, featured, pick, wide, duration, origin, banner, banner_en, blurb, blurb_en, about, about_en, poster, pw, ph, pos, shots, shotSize, dist, ord, at, packStatus, ownerId, embed) VALUES ('night-port', '夜航港', 'Night Port', 'yehanggang yehang', '林澄', '', '', 8.7, '9.6万', 0, 2026, 'story', '["工坊","叙事"]', 265, 0.11, 'story', '', 1, 1, 0, 1, 0, 1, 1, 'mid', '', '哪一盏灯继续亮着', '', '广播里只剩潮声。你要决定哪一盏灯继续亮着。', 'The radio is only tide. You decide which lamp stays on.', 'Fable 5.2 工坊示例。这是即玩站内做的简短示例，不是完整作品。', 'A Fable 5.2 workshop sample. This is a short sample built on Jiwan, not a full game.', 'Which lamp stays on', 960, 540, 'center', '["防波堤","值班室","最后一盏灯"]', '[]', '[3,6,12,22,57]', 71, 1794592579729, 'listed', 'lincheng', 1);
INSERT INTO games (id, title, title_en, pinyin, author, maker, source, score, players, plays, year, cat, tags, hue, chroma, play, src, demo, fable, hot, neu, featured, pick, wide, duration, origin, banner, banner_en, blurb, blurb_en, about, about_en, poster, pw, ph, pos, shots, shotSize, dist, ord, at, packStatus, ownerId, embed) VALUES ('lift', '电梯将至', 'Lift Incoming', 'diantijiangzhi dianti', '阿北', '', '', 8.1, '7.4万', 0, 2026, 'action', '["工坊","反应"]', 15, 0.14, 'story', '', 1, 1, 0, 1, 0, 0, 0, 'short', '', '', '', '楼层数字在跳。在门关上前把正确的人送回家。', 'Floor numbers jump. Get the right person home before the doors close.', 'Fable 5.2 工坊示例。这是即玩站内做的简短示例，不是完整作品。', 'A Fable 5.2 workshop sample. This is a short sample built on Jiwan, not a full game.', '', 960, 540, 'center', '["厅门","楼层灯","关门瞬间"]', '[]', '[5,10,20,28,37]', 72, 1794592579729, 'listed', '阿北', 1);
